<?php

declare(strict_types=1);

namespace ZeroForLaravel\Generation;

use LogicException;

/** Emits deployable registrations; never executes an HTTP action to sample its query. */
final readonly class ControllerQueryGenerator
{
    public function __construct(private SchemaDriver $schemas) {}

    /** @param list<ControllerQuery> $queries */
    public function typescript(array $queries, string $schemaImport): string
    {
        $lines = [
            '// Generated by Zero for Laravel. Deploy together with the PHP registrations.',
            "import {createBuilder, defineQueriesWithType, defineQueryWithType} from '@rocicorp/zero';",
            "import {liveQuery, withQueryInputs, encodeDate} from '@nickwelsh/zero-for-laravel';",
            "import type {ClientContext} from '@nickwelsh/zero-for-laravel';",
            $this->schemas->imports(),
            'import {schema, definitions} from '.json_encode($schemaImport, JSON_THROW_ON_ERROR).';',
            'const zql = createBuilder(schema);',
            'const defineQueries = defineQueriesWithType<typeof schema>();',
            'const defineQuery = defineQueryWithType<typeof schema, ClientContext>();',
            'export const inputs = {',
        ];
        foreach ($queries as $query) {
            $cursor = null;
            if ($query->expression->kind === 'paginate') {
                $cursor = [];
                foreach ($query->expression->cursorFields() as $field) {
                    $column = $query->expression->model?->columns[$field];
                    $type = match ($column['type'] ?? null) {
                        'string' => 'string', 'number' => 'float', 'boolean' => 'bool',
                        default => throw new LogicException('Unsupported cursor column '.$field),
                    };
                    $cursor[$field] = ($column['nullable'] ? 'nullable:' : '').$type;
                }
            }

            $lines[] = '  '.json_encode($query->name(), JSON_THROW_ON_ERROR).': '.$this->schemas->object($query->parameters, $cursor).',';
        }

        $lines[] = '};';
        $lines[] = 'export const publicInputs = {';
        foreach ($queries as $query) {
            $lines[] = '  '.json_encode($query->name(), JSON_THROW_ON_ERROR).': '.$this->schemas->object($query->parameters, public: true).',';
        }

        $lines[] = '};';
        $lines[] = 'export const queries = defineQueries({';
        foreach ($queries as $query) {
            $name = json_encode($query->name(), JSON_THROW_ON_ERROR);
            $lines[] = '  '.$name.': defineQuery(inputs['.$name.'], '.$query->typescript().'),';
        }

        $lines[] = '});';
        $lines[] = 'export const bindings = {';
        foreach ($queries as $query) {
            $name = json_encode($query->name(), JSON_THROW_ON_ERROR);
            $parse = $this->schemas->parse('inputs['.$name.']', 'args');
            $model = json_encode($query->expression->model?->name, JSON_THROW_ON_ERROR);
            $pageSize = in_array($query->expression->kind, ['infinite', 'paginate'], true) ? ', '.$query->expression->value : '';
            if ($query->expression->kind === 'paginate') {
                $pageSize .= ', '.json_encode($query->expression->cursorFields(), JSON_THROW_ON_ERROR);
            }

            $request = null;
            $options = [];
            foreach ($query->parameters as $parameter => $type) {
                if (str_starts_with($type, 'request:')) {
                    $request = $parameter;
                    foreach (RequestContract::value(substr($type, 8))->fields as $field => $contract) {
                        if (($choices = $contract->choices()) !== null) {
                            $options[$field] = $choices;
                        }
                    }
                }
            }

            $lines[] = '  '.$name.': (args: Parameters<typeof queries['.$name.']>[0]) => withQueryInputs(liveQuery(queries['.$name.'], '.$parse.', definitions, '.$model.', '.($query->expression->singular ? 'true' : 'false').$pageSize.'), '.$parse.', '.json_encode($request, JSON_THROW_ON_ERROR).', '.json_encode((object) $options, JSON_THROW_ON_ERROR).' as const, value => '.$this->schemas->parse('inputs['.$name.']', 'value').'),';
        }

        $lines[] = '};';
        $lines[] = 'export const actions = {';
        foreach ($queries as $query) {
            $name = json_encode($query->name(), JSON_THROW_ON_ERROR);
            $action = json_encode($query->action.'.'.$query->prop, JSON_THROW_ON_ERROR);
            $lines[] = '  '.$action.': (input: '.$this->schemas->inputType('publicInputs['.$name.']').') => { const args = '.$this->schemas->parse('publicInputs['.$name.']', 'input').'; return bindings['.$name.']('.$this->schemas->encode($query->parameters, 'args').'); },';
        }

        $lines[] = '};';

        return implode("\n", $lines)."\n";
    }

    /** @param list<ControllerQuery> $queries */
    public function php(array $queries): string
    {
        $lines = ['<?php', '', 'declare(strict_types=1);', '', '// Generated by Zero for Laravel. Do not edit.', 'return ['];
        foreach ($queries as $query) {
            $contracts = [];
            foreach ($query->parameters as $name => $type) {
                if (str_starts_with($type, 'request:')) {
                    $contracts[] = var_export($name, true).' => '.RequestContract::value(substr($type, 8))->php();
                }
            }

            $lines[] = '    '.var_export($query->name(), true).' => new \\ZeroForLaravel\\Query\\RegisteredQuery('.implode(', ', [
                var_export($query->action, true), var_export($query->component, true), var_export($query->prop, true),
                var_export($query->parameters, true), $query->php(), '['.implode(', ', $contracts).']',
            ]).'),';
        }

        $lines[] = '];';

        return implode("\n", $lines)."\n";
    }
}
